public sealed class HistoryPayloadLease : IDisposable
{
    readonly object gate = new();
    HistoryPayloadStore? owner;
    readonly HistoryPayloadStore.Entry entry;
    internal HistoryPayloadLease(HistoryPayloadStore owner, HistoryPayloadStore.Entry entry) { this.owner = owner; this.entry = entry; }
    public HistoryPayloadKind Kind => entry.Kind;
    public string? FilePath => entry.Path;
    public byte[] ReadBytes() { lock (gate) return Active.Read(entry); }
    public HistoryPayloadLease Retain() { lock (gate) return Active.Retain(entry); }
    HistoryPayloadStore Active => owner ?? throw new ObjectDisposedException(nameof(HistoryPayloadLease));
    public void Dispose()
    {
        lock (gate)
        {
            if (owner is null) return;
            var current = owner;
            try { current.Release(entry); owner = null; }
            catch { if (!current.IsLive(entry)) owner = null; throw; }
        }
    }
}

public void AdaptOldValue(Func<T, T> adapt)
{
    ArgumentNullException.ThrowIfNull(adapt);
    var previous = OldValue; var next = adapt(previous);
    if (ReferenceEquals(previous,next)) return;
    OldValue = next;
    ReleaseReplaced(previous);
}
/// <summary>Explicit host view-only adaptation; it never recaptures an action's new structure.</summary>
public void AdaptNewValue(Func<T, T> adapt)
{
    ArgumentNullException.ThrowIfNull(adapt);
    if (!IsDataComplete) throw new InvalidOperationException("The new payload has not been completed.");
    var previous = newValue; var next = adapt(previous);
    if (ReferenceEquals(previous,next)) return;
    newValue = next;
    ReleaseReplaced(previous);
}
internal void CompleteNewValue()
{
    IsDataComplete = true; // Source sets this before Update, including when capture throws.
    newValue = capture();
    hasNewValue = true;
}
